public class MainActivity extends Activity {
    private static final int INK=0xff123c32, GREEN=0xff175c48, LIME=0xffdcf587, BG=0xfff3f6f2,
            MUTED=0xff71837b, BORDER=0xffdfe7de, WHITE=Color.WHITE, RED=0xffa34236;
    private LinearLayout layout;
    private TextView message,fareValue,kmValue,secondsValue,stateLabel,gpsLabel,accuracyLabel,driverLabel,waitingHint;
    private EditText server,username,password;
    private Button start,waiting,pause,resume,finish,logout,loginButton;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private boolean busy=false,loggedIn=false;
    private String pending="start";
    private final Runnable refresh=new Runnable(){public void run(){render();handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);Engine.init(this);showLogin();}

    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private void gap(LinearLayout parent,int size){Space space=new Space(this);parent.addView(space,new LinearLayout.LayoutParams(1,dp(size)));}
    private TextView label(String value,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setFontFeatureSettings("tnum");v.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));v.setLineSpacing(dp(2),1.05f);return v;}
    private TextView addText(LinearLayout parent,String value,int size,int color,boolean bold){TextView v=label(value,size,color,bold);parent.addView(v);return v;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void weight(LinearLayout parent,View view,int right){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,0,dp(right),0);parent.addView(view,p);}
    private LinearLayout card(LinearLayout parent,int color,int padding){LinearLayout c=column();c.setPadding(dp(padding),dp(padding),dp(padding),dp(padding));c.setBackground(shape(color,24,color==WHITE?BORDER:0));parent.addView(c,new LinearLayout.LayoutParams(-1,-2));return c;}
    private void page(){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});layout=column();layout.setPadding(dp(22),dp(22),dp(22),dp(28));scroll.addView(layout);setContentView(scroll);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
    private void brand(LinearLayout parent,boolean dark){LinearLayout r=row();ImageView mark=new ImageView(this);mark.setImageResource(uk.payapi.kilotaxi.R.drawable.ic_taxi);mark.setBackground(shape(LIME,14,0));mark.setPadding(dp(10),dp(10),dp(10),dp(10));r.addView(mark,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout words=column();words.setPadding(dp(12),0,0,0);addText(words,"KILO TAXI",18,dark?WHITE:INK,true).setLetterSpacing(.08f);addText(words,"DRIVER APP",10,dark?0xffb9d3c4:MUTED,true).setLetterSpacing(.18f);r.addView(words);parent.addView(r);}
    private Button control(LinearLayout parent,String text,int bg,int fg,int border,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(15);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setAllCaps(false);b.setTextColor(fg);b.setGravity(Gravity.CENTER);b.setPadding(dp(16),dp(12),dp(16),dp(12));b.setMinHeight(dp(56));b.setMinimumHeight(dp(56));b.setStateListAnimator(null);b.setBackgroundTintList(null);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x20356048),shape(bg,16,border),null));b.setOnClickListener(v->action.run());if(parent!=null)parent.addView(b,new LinearLayout.LayoutParams(-1,-2));return b;}
    private void enabled(Button button,boolean value){button.setEnabled(value);button.setAlpha(value?1f:.38f);}
    private EditText field(LinearLayout parent,String title,String hint,String value,boolean secret){addText(parent,title,12,MUTED,true);gap(parent,7);EditText v=new EditText(this);v.setText(value);v.setHint(hint);v.setSingleLine(true);v.setTextSize(16);v.setTextColor(INK);v.setHintTextColor(0xff9ca9a0);v.setPadding(dp(16),dp(14),dp(16),dp(14));v.setInputType(InputType.TYPE_CLASS_TEXT|(secret?InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS));v.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));v.setBackground(shape(0xfff7f9f5,14,BORDER));v.setMinHeight(dp(54));v.setOnFocusChangeListener((view,focus)->view.setBackground(shape(focus?WHITE:0xfff7f9f5,14,focus?GREEN:BORDER)));parent.addView(v,new LinearLayout.LayoutParams(-1,-2));gap(parent,18);return v;}

    private void showLogin(){loggedIn=false;fareValue=null;page();LinearLayout hero=card(layout,INK,24);brand(hero,true);gap(hero,28);addText(hero,"သင့်ခရီးကို\nလွယ်ကူစွာ စီမံပါ",29,WHITE,true);gap(hero,12);addText(hero,"LIVE DISTANCE  /  WAITING  /  HISTORY",10,LIME,true).setLetterSpacing(.06f);gap(layout,22);LinearLayout form=card(layout,WHITE,22);addText(form,"အကောင့်ဝင်ရန်",24,INK,true);gap(form,6);addText(form,"Admin ပေးထားသော account ဖြင့် ဝင်ပါ။",13,MUTED,false);gap(form,24);username=field(form,"USERNAME","သင့် username ဖြည့်ပါ","",false);password=field(form,"PASSWORD","အနည်းဆုံး ၆ လုံး","",true);password.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);CheckBox show=new CheckBox(this);show.setText("Password ပြရန်");show.setTextSize(12);show.setTextColor(MUTED);show.setButtonTintList(ColorStateList.valueOf(GREEN));show.setPadding(0,0,0,dp(10));show.setOnCheckedChangeListener((b,checked)->{password.setTransformationMethod(checked?null:android.text.method.PasswordTransformationMethod.getInstance());password.setSelection(password.length());});form.addView(show);loginButton=control(form,"ဝင်မယ်  →",GREEN,WHITE,0,this::login);password.setOnEditorActionListener((v,id,event)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_DONE){login();return true;}return false;});gap(form,16);message=addText(form,"",13,RED,false);message.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);LinearLayout serverFields=column();server=field(serverFields,"HTTPS SERVER","https://your-server",Engine.origin(),false);serverFields.setVisibility(View.GONE);Button settings=control(form,"Server ပြင်ရန်  ⌄",WHITE,MUTED,0,()->serverFields.setVisibility(serverFields.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));settings.setMinHeight(dp(44));form.addView(serverFields);gap(layout,18);TextView footer=addText(layout,"လုံခြုံသော HTTPS ချိတ်ဆက်မှု · Password မသိမ်းပါ",11,MUTED,false);footer.setGravity(Gravity.CENTER);}
    private void login(){if(busy)return;try{String target=Engine.normalize(server.getText().toString());if(username.getText().toString().trim().isEmpty()||password.length()==0){message.setText("Username နှင့် password ဖြည့်ပါ။");return;}Engine.prefs.edit().putString("origin",target).remove("cookie").apply();JSONObject body=new JSONObject().put("username",username.getText().toString().trim()).put("password",password.getText().toString());busy=true;loginButton.setText("ဝင်နေပါတယ်…");enabled(loginButton,false);message.setText("");Engine.queue.execute(()->{try{Engine.user=Engine.call("login",body);Engine.apply(Engine.call("meter",null));runOnUiThread(()->{password.setText("");showMeter();});}catch(Exception e){runOnUiThread(()->message.setText(e.getMessage()));}finally{busy=false;runOnUiThread(()->{if(!loggedIn){loginButton.setText("ဝင်မယ်  →");enabled(loginButton,true);}else render();});}});}catch(Exception e){message.setText(e.getMessage());}}

    private void showMeter(){loggedIn=true;page();brand(layout,false);gap(layout,24);LinearLayout heading=row();weight(heading,label("တိုက်ရိုက်မီတာ",23,INK,true),8);stateLabel=label("READY",10,GREEN,true);stateLabel.setPadding(dp(12),dp(6),dp(12),dp(6));stateLabel.setBackground(shape(0xffe5efd8,30,0));heading.addView(stateLabel);layout.addView(heading);driverLabel=addText(layout,Engine.user==null?"ယာဉ်မောင်း":Engine.user.optString("name")+"  ·  "+Engine.user.optString("vehicleNumber","—"),13,MUTED,false);gap(layout,18);
        LinearLayout fare=card(layout,INK,24);addText(fare,"စုစုပေါင်း ခရီးခ",13,0xffc3d6ca,false);gap(fare,8);LinearLayout amount=row();fareValue=label("0",48,WHITE,true);fareValue.setMaxLines(1);fareValue.setGravity(Gravity.CENTER_VERTICAL);fareValue.setAutoSizeTextTypeUniformWithConfiguration(28,48,1,android.util.TypedValue.COMPLEX_UNIT_SP);amount.addView(fareValue,new LinearLayout.LayoutParams(0,dp(78),1));TextView currency=label("ကျပ်",16,LIME,true);currency.setPadding(dp(12),dp(18),0,0);amount.addView(currency);fare.addView(amount);gap(fare,12);View divider=new View(this);divider.setBackgroundColor(0xff3c6052);fare.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));gap(fare,14);addText(fare,"ခရီးခကို Admin သတ်မှတ်ထားသော နှုန်းဖြင့် တွက်ပါတယ်။",11,0xffbdd1c3,false);gap(layout,14);
        LinearLayout metrics=row();LinearLayout distance=column(),wait=column();distance.setBackground(shape(WHITE,20,BORDER));wait.setBackground(shape(WHITE,20,BORDER));distance.setPadding(dp(17),dp(18),dp(17),dp(18));wait.setPadding(dp(17),dp(18),dp(17),dp(18));addText(distance,"ခရီးအကွာအဝေး",11,MUTED,true);gap(distance,8);kmValue=addText(distance,"0.000",27,INK,true);addText(distance,"ကီလိုမီတာ · km",10,MUTED,false);addText(wait,"စောင့်ဆိုင်းချိန်",11,MUTED,true);gap(wait,8);secondsValue=addText(wait,"0",27,INK,true);addText(wait,"စက္ကန့်",10,MUTED,false);weight(metrics,distance,10);weight(metrics,wait,0);layout.addView(metrics);gap(layout,14);
        LinearLayout waitingCard=card(layout,0xffeaf1df,17);waitingHint=addText(waitingCard,"ပထမ ၁၀ မိနစ် စောင့်ခ အခမဲ့",12,GREEN,true);gap(waitingCard,10);waiting=control(waitingCard,"Waiting ON · စောင့်ချိန်စမယ်",WHITE,INK,BORDER,()->requestTrack("waiting"));gap(layout,20);
        start=control(layout,"ခရီးစမယ်  →",LIME,INK,0,()->requestTrack("start"));LinearLayout actions=row();pause=control(null,"Ⅱ  ခေတ္တရပ်မယ်",WHITE,INK,BORDER,()->action("pause"));resume=control(null,"▶  ပြန်စမယ်",GREEN,WHITE,0,()->requestTrack("resume"));weight(actions,pause,8);weight(actions,resume,0);layout.addView(actions);gap(layout,10);finish=control(layout,"ခရီးဆုံး · မှတ်တမ်းသိမ်းမယ်",0xfffff3ee,RED,0xffeed9d0,()->new AlertDialog.Builder(this).setTitle("ခရီးဆုံးမလား?").setMessage("ခရီးနှင့် လမ်းကြောင်းကို History ထဲ သိမ်းပါမယ်။").setNegativeButton("မဆုံးသေးပါ",null).setPositiveButton("သိမ်းမယ်",(d,w)->action("finish")).show());gap(layout,20);
        LinearLayout gps=card(layout,WHITE,18);LinearLayout gpsRow=row();gpsLabel=label("●  GPS OFF",12,MUTED,true);weight(gpsRow,gpsLabel,8);accuracyLabel=label("—",12,MUTED,false);gpsRow.addView(accuracyLabel);gps.addView(gpsRow);gap(gps,8);message=addText(gps,Engine.status,12,MUTED,false);message.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);gap(layout,12);LinearLayout links=row();Button history=control(null,"↗  ခရီးမှတ်တမ်း",BG,GREEN,0,()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(Engine.origin()+"/history"))));logout=control(null,"Logout",BG,MUTED,0,this::logout);weight(links,history,8);weight(links,logout,0);layout.addView(links);gap(layout,6);addText(layout,"ခရီးစနေချိန် screen ပိတ်ထားလည်း GPS ဆက်မှတ်ပါတယ်။\nPause / ခရီးဆုံးမှာ GPS ရပ်ပါမယ်။ Internet ပြတ်ချိန်က km ကို ခန့်မှန်းမဖြည့်ပါ။",10,MUTED,false);render();}
    private void logout(){if(Engine.active()||busy)return;Engine.queue.execute(()->{try{Engine.call("logout",new JSONObject());}catch(Exception ignored){}Engine.prefs.edit().remove("cookie").apply();runOnUiThread(this::showLogin);});}
    private boolean mayDrive(){if(Engine.user==null||Engine.user.optJSONArray("permissions")==null)return false;String permissions=Engine.user.optJSONArray("permissions").toString();return permissions.contains("calculate")&&permissions.contains("save_trips");}
    private void render(){if(!loggedIn||fareValue==null)return;if(Engine.prefs.getString("cookie","").isEmpty()&&!Engine.tracking){showLogin();return;}JSONObject m=Engine.meter;long seconds=m==null?0:(long)m.optDouble("waitingSeconds");if(m!=null&&Engine.tracking&&m.optBoolean("waitingEnabled")&&!"paused".equals(m.optString("state")))seconds+=Math.min(30,Math.max(0,(System.currentTimeMillis()-Engine.receivedAt)/1000));fareValue.setText(String.format(Locale.US,"%,.0f",m==null?0:m.optDouble("total")));kmValue.setText(String.format(Locale.US,"%.3f",m==null?0:m.optDouble("km")));secondsValue.setText(String.valueOf(seconds));String state=m==null?"OFF":m.optString("state");stateLabel.setText(state.equals("driving")?"မောင်းနေ":state.equals("waiting")?"စောင့်နေ":state.equals("paused")?"ရပ်ထား":state.equals("finished")?"ခရီးဆုံး":"READY");gpsLabel.setText(Engine.tracking?"●  BACKGROUND GPS ON":"○  GPS OFF");gpsLabel.setTextColor(Engine.tracking?GREEN:MUTED);accuracyLabel.setText("Accuracy  "+Engine.accuracy);message.setText(Engine.status);boolean active=Engine.active(),paused=state.equals("paused"),allowed=mayDrive()&&!busy,on=m!=null&&m.optBoolean("waitingEnabled");waitingHint.setText(seconds<=600?"ပထမ ၁၀ မိနစ် အခမဲ့ · ကျန် "+Math.max(0,600-seconds)+" စက္ကန့်":"အခကောက်သော စောင့်ချိန် "+(seconds-600)+" စက္ကန့်");waiting.setText(on?"●  Waiting ON · ရပ်မယ်":"Waiting OFF · စောင့်ချိန်စမယ်");waiting.setBackgroundTintList(ColorStateList.valueOf(on?LIME:WHITE));enabled(waiting,allowed&&active&&!paused);start.setVisibility(active&&Engine.tracking?View.GONE:View.VISIBLE);start.setText(busy?"လုပ်ဆောင်နေပါတယ်…":active?"⌖  GPS ပြန်ချိတ်မယ်":"ခရီးစမယ်  →");enabled(start,allowed&&!Engine.tracking);pause.setVisibility(active&&!paused?View.VISIBLE:View.GONE);resume.setVisibility(active&&paused?View.VISIBLE:View.GONE);enabled(pause,allowed&&active&&!paused);enabled(resume,allowed&&active&&paused);enabled(finish,allowed&&active);enabled(logout,!busy&&!active);}
    private void requestTrack(String action){pending=action;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setTitle("ခရီးအတွင်း GPS အသုံးပြုခွင့်").setMessage("ခရီး km နဲ့ history လမ်းကြောင်းမှတ်ရန် Precise Location လိုပါတယ်။ ခရီးစနေချိန် app ကို နောက်ခံပို့ထားလည်း notification နဲ့ GPS ဆက်မှတ်ပါမယ်။").setNegativeButton("မလုပ်သေးပါ",null).setPositiveButton("ခွင့်ပြုမယ်",(d,w)->{String[] permissions=Build.VERSION.SDK_INT>=33?new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.POST_NOTIFICATIONS}:new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION};requestPermissions(permissions,7);}).show();return;}action(action);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==7){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)action(pending);else new AlertDialog.Builder(this).setMessage("Precise Location ခွင့်ပြုပါ။ ပိတ်ထားပြီးသားဆို App Settings မှာ ပြန်ဖွင့်ပါ။").setPositiveButton("Settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())))).setNegativeButton("ပိတ်ရန်",null).show();}}
    private void action(String action){if(busy)return;busy=true;render();Engine.queue.execute(()->{try{if(action.equals("start")){if(!Engine.active())Engine.apply(Engine.call("meter/start",new JSONObject()));else Engine.apply(Engine.call("meter",null));}else{String type=action.equals("waiting")?(Engine.meter.optBoolean("waitingEnabled")?"waiting_off":"waiting_on"):action;Engine.apply(Engine.call("meter/"+Engine.meter.getString("id"),new JSONObject().put("type",type)));}Engine.status="မီတာ sync ဖြစ်နေပါတယ်။";runOnUiThread(()->{try{if(Engine.shouldTrack())startForegroundService(new Intent(this,TrackingService.class));else stopService(new Intent(this,TrackingService.class));}catch(Exception e){Engine.status="App ကို အရှေ့မှာဖွင့်ပြီး GPS ဆက်ချိတ်မယ် ကိုနှိပ်ပါ။ "+e.getMessage();}});}catch(Exception e){Engine.status=e.getMessage();}finally{busy=false;runOnUiThread(this::render);}});}
    @Override protected void onResume(){super.onResume();handler.post(refresh);if(!loggedIn&&!Engine.prefs.getString("cookie","").isEmpty()){Engine.queue.execute(()->{try{Engine.user=Engine.call("me",null);Engine.apply(Engine.call("meter",null));runOnUiThread(this::showMeter);}catch(Exception e){Engine.status=e.getMessage();}});}}
    @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
